class ScoreTracker:
    """Keep a running total and count of scores added."""

    def __init__(self, starting_score=0):
        self.total = starting_score
        self.count = 0

    def add_score(self, points):
        self.total += points
        self.count += 1

    def average(self):
        if self.count == 0:
            return 0
        return self.total / self.count


import unittest


class TestScoreTracker(unittest.TestCase):
    def setUp(self):
        self.tracker = ScoreTracker()

    def test_add_score_updates_total(self):
        self.tracker.add_score(10)
        self.assertEqual(self.tracker.total, 10)

    def test_average_returns_mean_of_scores(self):
        self.tracker.add_score(10)
        self.tracker.add_score(20)
        self.assertEqual(self.tracker.average(), 15)
